/**
 * Expiring contracts (/recompetes/<slug>) — numbered child 3 (the last) of the recompete family.
 * Answers 503 if the gated set outgrows all children — add a child rather than truncate.
 * Generated by src/lib/seo/sitemap-sections.ts (recompeteEntries); listed in the sitemap index.
 */
import { renderUrlset, sitemapResponse, sitemapFailure } from '@/lib/seo/sitemap-xml';
import { recompeteEntries } from '@/lib/seo/sitemap-sections';

// Rendered per request, cached at the CDN, so a read failure answers 503 instead of being
// frozen into a build artifact.
export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    return sitemapResponse(renderUrlset(await recompeteEntries(2)));
  } catch (err) {
    return sitemapFailure('recompetes-3', err);
  }
}
